INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0.5, 1, 115711, 0, "ここメルクリゾートではプールサイドで\nたい焼きを売る怪人の噂がある。", 0, 0, 923, 11, 19230017, 10);
