INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0.5, 1, 115711, 0, "フードコートで売っているのであれば\n何ら違和感はないけれど。", 0, 0, 923, 11, 19230021, 10);
