INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 1, 117411, 0, "はぁ、レイ様…♡\n流れる姿も麗しいですね。\nずっと見ていられるぅ…", 0, 0, 943, 11, 19430034, 7);
