INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", 2, 0.2, "cmn_boat_idle", "", "", 944, 3, 19440028, 1);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", 0, "vo_fpc", "", "vo_fpc_30403", "", "", 944, 21, 19440029, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 1, 126811, 0, "あら、タマキさんじゃない。\nこんなところで何やってるの？", 0, 0, 944, 11, 19440030, 10);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", 0, "", "", "", "", 944, 91, 19440031, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", 0, "vo_fpc", "", "vo_fpc_30404", "", "", 944, 21, 19440032, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 1, 107911, 0, "なんだ、ユカリだったかにゃ。\n何ってもちろん商売にゃ！", 0, 0, 944, 11, 19440033, 10);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", 0, "", "", "", "", 944, 91, 19440034, "");
