INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", 0, "vo_fpc", "", "vo_fpc_30405", "", "", 944, 21, 19440037, "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 1, 107911, 0, "こんなに人がいっぱいいる商機、\n見逃すわけにはいかないにゃ！", 0, 0, 944, 11, 19440038, 10);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", 0, "", "", "", "", 944, 91, 19440039, "");
