INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0.5, 1, 107911, 0, "大丈夫にゃ。バレないように…\nってやばいにゃ！　見回りだにゃ！", 0, 0, 944, 11, 19440046, 8);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", 0, "", "", "", "", 944, 91, 19440047, "");
